CREATE TABLE IF NOT EXISTS raw_documents (raw_id TEXT PRIMARY KEY, url TEXT, canonical_url TEXT NOT NULL, domain TEXT, fetched_at TEXT, http_status INTEGER, content_type TEXT, content_hash TEXT NOT NULL, size_bytes INTEGER, blob_path TEXT, source_id TEXT, parent_url TEXT, task_id TEXT, fetch_method TEXT CHECK(fetch_method IN ('http','browser','api')), extractor_ver_hint TEXT, outcome TEXT CHECK(outcome IN ('ok','login_wall','empty_body','blocked','error')), UNIQUE(canonical_url,content_hash));
CREATE TABLE IF NOT EXISTS fetch_log (id INTEGER PRIMARY KEY, url TEXT, domain TEXT, ts TEXT, status INTEGER, kind TEXT, bytes INTEGER);
CREATE TABLE IF NOT EXISTS extractions (extraction_id TEXT PRIMARY KEY, raw_id TEXT NOT NULL REFERENCES raw_documents(raw_id), extractor TEXT NOT NULL, extractor_version TEXT NOT NULL, doc_type TEXT, lang TEXT, title TEXT, text_hash TEXT, structured TEXT, mentions TEXT, links TEXT, dates TEXT, amounts TEXT, created_at TEXT, UNIQUE(raw_id,extractor,extractor_version));
CREATE TABLE IF NOT EXISTS labels (label_id TEXT PRIMARY KEY, raw_id TEXT REFERENCES raw_documents(raw_id), extraction_id TEXT REFERENCES extractions(extraction_id), kind TEXT CHECK(kind IN ('doc_type','event_type','claim')), value TEXT, status TEXT CHECK(status IN ('fact','source_claim','ai_inference','unverified')), rule_id TEXT, created_at TEXT, UNIQUE(raw_id,kind,value,rule_id));
CREATE TABLE IF NOT EXISTS observations (obs_id TEXT PRIMARY KEY, venue_key TEXT NOT NULL, field TEXT NOT NULL, value_json TEXT, value_text TEXT, value_hash TEXT NOT NULL, unit TEXT, label_status TEXT CHECK(label_status IN ('fact','source_claim','ai_inference','unverified')), source_url TEXT, source_type TEXT CHECK(source_type IN ('own_site','official_directory','third_party','aggregator','sns','attachment')), quote TEXT CHECK(length(quote)<=240), locator TEXT, raw_id TEXT REFERENCES raw_documents(raw_id), extraction_id TEXT REFERENCES extractions(extraction_id), extractor_version TEXT, rule_id TEXT, observed_at TEXT, UNIQUE(venue_key,field,value_hash,raw_id));
CREATE TABLE IF NOT EXISTS venues (venue_id TEXT PRIMARY KEY, venue_key TEXT NOT NULL UNIQUE, name TEXT, name_ko TEXT, type TEXT, region TEXT, city TEXT, website TEXT, domains TEXT, is_seed INTEGER DEFAULT 0, seed_match TEXT, discovered_via TEXT, first_seen_at TEXT, state TEXT CHECK(state IN ('active','opening_soon','closed','unknown')));
CREATE TABLE IF NOT EXISTS venue_aliases (alias_id TEXT PRIMARY KEY, venue_id TEXT REFERENCES venues(venue_id), alias TEXT, normalized_name TEXT, UNIQUE(venue_id,normalized_name));
CREATE TABLE IF NOT EXISTS venue_links (link_id TEXT PRIMARY KEY, venue_id TEXT REFERENCES venues(venue_id), url TEXT, kind TEXT, discovered_via TEXT, UNIQUE(venue_id,url,kind));
CREATE TABLE IF NOT EXISTS venue_fields (vf_id TEXT PRIMARY KEY, venue_id TEXT REFERENCES venues(venue_id), field TEXT, value_json TEXT, value_text TEXT, value_hash TEXT, unit TEXT, label_status TEXT, source_url TEXT, quote TEXT, obs_id TEXT REFERENCES observations(obs_id), valid_from TEXT, valid_to TEXT, superseded_by TEXT REFERENCES venue_fields(vf_id), UNIQUE(venue_id,field,value_hash,valid_from));
CREATE TABLE IF NOT EXISTS field_changes (change_id TEXT PRIMARY KEY, venue_id TEXT REFERENCES venues(venue_id), field TEXT, old_value TEXT, new_value TEXT, old_value_hash TEXT, new_value_hash TEXT, old_obs_id TEXT REFERENCES observations(obs_id), new_obs_id TEXT REFERENCES observations(obs_id), detected_at TEXT, UNIQUE(venue_id,field,old_value_hash,new_value_hash));
CREATE TABLE IF NOT EXISTS confirmations (confirmation_id TEXT PRIMARY KEY, vf_id TEXT REFERENCES venue_fields(vf_id), obs_id TEXT REFERENCES observations(obs_id), last_confirmed_at TEXT, UNIQUE(vf_id,obs_id));
CREATE TABLE IF NOT EXISTS seed_venues (seed_venue_id TEXT PRIMARY KEY, seed_id TEXT NOT NULL, name TEXT, normalized_name TEXT, domain TEXT, website TEXT, frozen_at TEXT, UNIQUE(seed_id,normalized_name,domain));
CREATE TABLE IF NOT EXISTS seed_domains (seed_domain_id TEXT PRIMARY KEY, seed_id TEXT NOT NULL, domain TEXT NOT NULL, frozen_at TEXT, UNIQUE(seed_id,domain));
CREATE TABLE IF NOT EXISTS sources (source_id TEXT PRIMARY KEY, domain TEXT NOT NULL UNIQUE, url TEXT, state TEXT, reason TEXT, quality REAL, source_type TEXT, first_seen_at TEXT, last_seen_at TEXT, next_at TEXT, discovered_via TEXT);
CREATE TABLE IF NOT EXISTS source_trials (trial_id TEXT PRIMARY KEY, source_id TEXT REFERENCES sources(source_id), url TEXT, relevance REAL, novelty REAL, extractability REAL, original REAL, total REAL, decision TEXT, reason TEXT, created_at TEXT, UNIQUE(source_id,url));
CREATE TABLE IF NOT EXISTS tasks (task_id TEXT PRIMARY KEY, dedupe_key TEXT NOT NULL UNIQUE, url TEXT, domain TEXT, kind TEXT, task_class TEXT CHECK(task_class IN ('backfill','discover','freshness')), state TEXT DEFAULT 'pending' CHECK(state IN ('pending','running','done','failed','dead')), payload TEXT, source_id TEXT, venue_id TEXT, parent_url TEXT, parent_task_id TEXT, discovered_via TEXT, depth INTEGER DEFAULT 0 CHECK(depth<=2), priority REAL, novelty REAL, gap_importance REAL, urgency REAL, source_quality REAL, cost REAL, duplication REAL, repeat_failures INTEGER DEFAULT 0, attempts INTEGER DEFAULT 0, next_at TEXT, lease_until TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS gaps (gap_id TEXT PRIMARY KEY, venue_id TEXT REFERENCES venues(venue_id), field TEXT, state TEXT, evidence_url TEXT, obs_id TEXT REFERENCES observations(obs_id), reason TEXT, next_at TEXT, updated_at TEXT, UNIQUE(venue_id,field));
CREATE TABLE IF NOT EXISTS gap_attempts (attempt_id TEXT PRIMARY KEY, gap_id TEXT REFERENCES gaps(gap_id), strategy TEXT, url TEXT, state TEXT, task_id TEXT, reason TEXT, created_at TEXT, UNIQUE(gap_id,strategy,url));
CREATE TABLE IF NOT EXISTS review_queue (review_id TEXT PRIMARY KEY, kind TEXT, venue_id TEXT, source_id TEXT, dedupe_key TEXT UNIQUE, details TEXT, state TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS failures (failure_id TEXT PRIMARY KEY, task_id TEXT, url TEXT, domain TEXT, reason TEXT, state TEXT, attempts INTEGER DEFAULT 0, next_at TEXT, created_at TEXT, UNIQUE(task_id,url,reason));
CREATE TABLE IF NOT EXISTS runs (run_id TEXT PRIMARY KEY, started_at TEXT, finished_at TEXT, state TEXT, max_requests INTEGER, max_minutes REAL, requests INTEGER DEFAULT 0, stats TEXT);
CREATE TABLE IF NOT EXISTS run_checkpoints (checkpoint_id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(run_id), task_id TEXT, kind TEXT, cursor TEXT, updated_at TEXT, UNIQUE(run_id,task_id,kind));
CREATE TABLE IF NOT EXISTS run_lease (lease_key TEXT PRIMARY KEY, run_id TEXT, heartbeat TEXT, lease_until TEXT);
CREATE TABLE IF NOT EXISTS structure_baselines (baseline_id TEXT PRIMARY KEY, source_id TEXT, page_type TEXT, signature TEXT, field_ids TEXT, updated_at TEXT, UNIQUE(source_id,page_type));
CREATE TABLE IF NOT EXISTS structure_alerts (alert_id TEXT PRIMARY KEY, source_id TEXT, page_type TEXT, raw_id TEXT, old_signature TEXT, new_signature TEXT, similarity REAL, reason TEXT, created_at TEXT, UNIQUE(source_id,page_type,raw_id));
CREATE TABLE IF NOT EXISTS budgets_daily (day TEXT NOT NULL, kind TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0 CHECK(used>=0), PRIMARY KEY(day,kind));
CREATE TABLE IF NOT EXISTS request_log (request_id INTEGER PRIMARY KEY, url TEXT, domain TEXT, ts TEXT, status INTEGER, kind TEXT, bytes INTEGER, outcome TEXT, run_id TEXT);
CREATE TABLE IF NOT EXISTS robots_cache (origin TEXT PRIMARY KEY, body TEXT, status INTEGER, fetched_at TEXT, expires_at TEXT, allowed INTEGER, reason TEXT);
CREATE TABLE IF NOT EXISTS provider_state (provider TEXT PRIMARY KEY, state TEXT, reason TEXT, next_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS taxonomy_candidates (candidate_id TEXT PRIMARY KEY, kind TEXT, value TEXT, raw_id TEXT, state TEXT, created_at TEXT, UNIQUE(kind,value,raw_id));
